#' Bootstrap Confidence Intervals for Hofmann's Index (CHof)
#'
#' @description
#' Computes asymmetric bootstrap confidence intervals for Hofmann's (1977) 
#' factorial complexity index at the item and/or factor level, based on a 
#' \code{facomplexBoot} object generated by \code{\link{bootLoadings}}.
#'
#' @param boot_result A \code{facomplexBoot} object.
#' @param level Character. One of \code{"item"}, \code{"factor"}, or 
#'   \code{"both"}.
#' @param scaledVersion Logical. If \code{TRUE}, adds \code{CHof.R} 
#'   (complexity scaled from 0 to 1).
#' @param simplVersion Logical. If \code{TRUE}, adds \code{CHof.S} 
#'   (simplicity scaled from 0 to 1).
#' @param includeMean Logical. If \code{TRUE}, adds a row \code{unit = "mean"} 
#'   with the average of the items (item level only).
#' @param conf.level Confidence level. If \code{NULL}, inherits from 
#'   \code{boot_result}.
#' @param type Character. \code{"perc"} (percentile) or \code{"bc"} 
#'   (bias-corrected). If \code{NULL}, inherits from \code{boot_result}.
#'
#' @return A \code{data.frame} with columns \code{level}, \code{unit},
#'   \code{index}, \code{estimate}, \code{lwr.ci}, \code{upr.ci},
#'   \code{conf.level}, and \code{type}.
#'
#' @details
#' For each bootstrap replica, \code{\link{Hofmann}} (item level) or
#' \code{\link{HofmannFac}} (factor level) is recalculated. Confidence 
#' intervals are constructed using the empirical quantiles of the replicates 
#' (percentile method) or with bias correction (\code{"bc"}).
#'
#' @seealso \code{\link{bootLoadings}}, \code{\link{Hofmann}},
#'   \code{\link{HofmannFac}}
#'
#' @examples
#' \donttest{
#' data(HolzingerSwineford1939, package = "lavaan")
#' d <- HolzingerSwineford1939[, paste0("x", 1:9)]
#' br <- bootLoadings(d, nfactors = 3, R = 50)
#'
#' ciHofmann(br)
#' ciHofmann(br, level = "factor")
#' ciHofmann(br, level = "both", scaledVersion = TRUE, simplVersion = TRUE)
#' }
#' @export
ciHofmann <- function(boot_result,
                      level = c("item", "factor", "both"),
                      scaledVersion = FALSE,
                      simplVersion = FALSE,
                      includeMean = TRUE,
                      conf.level = NULL,
                      type = NULL) {
  
  if (!inherits(boot_result, "facomplexBoot"))
    stop("'boot_result' must be an object returned by bootLoadings().")
  
  level <- match.arg(level)
  conf.level <- conf.level %||% boot_result$conf.level
  type       <- type       %||% boot_result$type
  
  L0 <- boot_result$loadings_original
  Lb <- boot_result$loadings_boot
  R  <- boot_result$R
  p  <- nrow(L0); r <- ncol(L0)
  item_names   <- rownames(L0)
  factor_names <- colnames(L0)
  
  rows <- list()
  
  # --- ITEM LEVEL ---
  if (level %in% c("item", "both")) {
    est <- Hofmann(as.data.frame(L0),
                   scaledVersion = scaledVersion,
                   simplVersion = simplVersion)
    
    boot_list_items <- lapply(seq_len(R), function(i) {
      L <- Lb[i, , ] # Extracts matrix preserving names
      if (anyNA(L)) return(NULL)
      tryCatch(
        Hofmann(as.data.frame(L),
                scaledVersion = scaledVersion,
                simplVersion = simplVersion),
        error = function(e) NULL)
    })
    
    for (col in names(est)) {
      mat <- do.call(rbind, lapply(boot_list_items, function(df) {
        if (is.null(df) || !col %in% names(df)) return(rep(NA_real_, p))
        v <- df[[col]]; if (length(v) != p) rep(NA_real_, p) else v
      }))
      for (k in seq_len(p)) {
        ci <- computeCI(mat[, k], est[[col]][k], conf.level, type)
        rows[[length(rows) + 1L]] <- buildRow(
          "item", item_names[k], col, est[[col]][k], ci, conf.level, type)
      }
      if (includeMean) {
        mean_est  <- mean(est[[col]], na.rm = TRUE)
        mean_boot <- apply(mat, 1, mean, na.rm = TRUE)
        ci <- computeCI(mean_boot, mean_est, conf.level, type)
        rows[[length(rows) + 1L]] <- buildRow(
          "item", "mean", col, mean_est, ci, conf.level, type)
      }
    }
  }
  
  # --- FACTOR LEVEL ---
  if (level %in% c("factor", "both")) {
    est_f <- HofmannFac(as.data.frame(L0))
    col <- names(est_f)[1]
    
    boot_list_factors <- lapply(seq_len(R), function(i) {
      L <- Lb[i, , ] # Extracts matrix preserving names
      if (anyNA(L)) return(NULL)
      tryCatch(
        HofmannFac(as.data.frame(L)),
        error = function(e) NULL)
    })
    
    mat <- do.call(rbind, lapply(boot_list_factors, function(df) {
      if (is.null(df) || !col %in% names(df)) return(rep(NA_real_, r))
      v <- df[[col]]; if (length(v) != r) rep(NA_real_, r) else v
    }))
    
    for (k in seq_len(r)) {
      ci <- computeCI(mat[, k], est_f[[col]][k], conf.level, type)
      rows[[length(rows) + 1L]] <- buildRow(
        "factor", factor_names[k], col, est_f[[col]][k], ci, conf.level, type)
    }
  }
  
  out <- do.call(rbind, rows); rownames(out) <- NULL
  attr(out, "boot_result") <- boot_result
  out
}